import { useState } from 'react';
import {
  JxToggle,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxBadge,
} from '@jinx-ui/react';

type ThemeValue = 'light' | 'dark' | 'system';

export interface AppearanceSettings {
  theme: ThemeValue;
  scale: number;
  dense: boolean;
  fontFamily: string;
}

const themeItems: Array<{ value: ThemeValue; label: string }> = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const fontOptions = [
  { value: 'sans', label: 'Inter Tight', meta: 'Без засечек' },
  { value: 'display', label: 'Fraunces', meta: 'С засечками' },
  { value: 'mono', label: 'JetBrains Mono', meta: 'Моноширинный' },
];

function AppearanceSettingsScreen({
  defaultSettings = { theme: 'system', scale: 100, dense: false, fontFamily: 'sans' },
  onChange,
}: {
  defaultSettings?: AppearanceSettings;
  onChange?: (settings: AppearanceSettings) => void;
}) {
  const [settings, setSettings] = useState<AppearanceSettings>(defaultSettings);

  const update = (patch: Partial<AppearanceSettings>) => {
    setSettings((prev) => {
      const next = { ...prev, ...patch };
      onChange?.(next);
      return next;
    });
  };

  const themeLabel =
    themeItems.find((item) => item.value === settings.theme)?.label ?? settings.theme;

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '24px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <header style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '20px',
            color: 'var(--jx-text)',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent" dot>
          {themeLabel}
        </JxBadge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <span style={{ fontSize: '13px', color: 'var(--jx-text-2)' }}>Тема оформления</span>
        <JxToggle
          items={themeItems}
          value={settings.theme}
          onValueChange={(value) => update({ theme: value as ThemeValue })}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(value) => update({ scale: value })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.dense}
        onChange={(event) => update({ dense: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        placeholder="Выберите шрифт"
        options={fontOptions}
        value={settings.fontFamily}
        onValueChange={(value) => update({ fontFamily: value })}
      />
    </section>
  );
}

export default AppearanceSettingsScreen;

